# Lesson 2, part 2: the players. Hedger, margin, speculator, who is who, and the danger.
# Styles for these slides: css/c.css


def _C_GT(head, rows, start=1, cls='', fixed=1):
    """Like GT, but the first `fixed` columns are given data: they stay visible, and only the computed cells appear click by click."""
    n = start
    h = ''.join(f'<th>{TX(x)}</th>' for x in head)
    b = ''
    for r in rows:
        tds = ''
        for j, c in enumerate(r):
            inner = f'<b class="gv">{TX(c[0])}</b><span class="gm">{TX(c[1])}</span>' if isinstance(c, tuple) else f'<b class="gv">{TX(c)}</b>'
            if j < fixed:
                tds += f'<td>{inner}</td>'
            else:
                tds += f'<td>{ST(n, inner)}</td>'
                n += 1
        b += f'<tr>{tds}</tr>'
    return f'<table class="tbl2 steptbl {cls}"><tr>{h}</tr>{b}</table>', n


