# ---------------------------------------------------------------- the hedger: Dana's Forward, cell by cell
_t, _n = _C_GT(['השער בעוד שלושה חודשים ($S_{T}$)', 'התשלום לספק (ש״ח)', 'תוצאת החוזה (ש״ח)', 'העלות נטו לדנה (ש״ח)'], [
    ['3.20', ('1,600,000', '$500,000 × 3.20$'), ('$-175,000$', '$500,000 × (3.20 − 3.55)$'), ('1,775,000', '$1,600,000 − (−175,000)$')],
    ['3.55', ('1,775,000', '$500,000 × 3.55$'), ('0', '$500,000 × (3.55 − 3.55)$'), ('1,775,000', '$1,775,000 − 0$')],
    ['3.90', ('1,950,000', '$500,000 × 3.90$'), ('175,000', '$500,000 × (3.90 − 3.55)$'), ('1,775,000', '$1,950,000 − 175,000$')]], 1, 'c-tb')
S('s-hedger', 'מגדר: דנה נועלת שער', 'מגדר (Hedger): דנה קונה חוזה אקדמה (Forward)',
  '<div class="card qstem"><p>' + TX('דנה, יבואנית רהיטים, תשלם לספק 500,000 דולר בעוד שלושה חודשים. היא לא רוצה להיות חשופה לשער הדולר, ולכן היא קונה (Long) כבר היום חוזה אקדמה (Forward) על 500,000 דולר, במחיר חוזה ($K$) של 3.55 ש״ח לדולר. את השער בעוד שלושה חודשים נסמן $S_{T}$.') + '</p><p>'
  + TX('<b>נדרש:</b> לכל שער אפשרי בעוד שלושה חודשים, 3.20, 3.55 או 3.90, חשבו את התשלום לספק בשקלים, את תוצאת החוזה ואת העלות נטו לדנה.') + '</p></div>'
  + '<div class="row top c-r2">' + _t
  + '<div class="card c-fm"><b class="ct">📐 הנוסחאות</b>'
  + '<p>' + TX('<b>תשלום לספק</b> = כמות × $S_{T}$') + '</p>'
  + '<p>' + TX('<b>תוצאת החוזה</b> = כמות × ($S_{T} − K$)') + '</p>'
  + '<p class="c-why">' + TX('דנה קונה ב-$K$ = 3.55 דולרים ששווים בשוק $S_{T}$.') + '</p>'
  + '<p>' + TX('<b>עלות נטו</b> = תשלום לספק − תוצאת החוזה') + '</p>'
  + '<p class="c-why">' + TX('כאן: כמות = 500,000 דולר.') + '</p></div></div>'
  + BAND('dg', 'בכל שער העלות נטו 1,775,000 ש״ח, כלומר $500,000 × 3.55$: ודאות, לא רווח. בשער 3.20, בלי החוזה, דנה הייתה משלמת רק 1,600,000 ש״ח. זה המחיר של הוודאות.', _n), kick=f'חלק {CUR[0]} · בנייה בהדרגה')

# ---------------------------------------------------------------- the hedger in Excel
_d = {'A1': 'כמות (דולר)', 'B1': 500000, 'A2': 'מחיר החוזה (K)', 'B2': 3.55, 'A4': 'שער בפקיעה', 'B4': 'תשלום לספק (ש״ח)', 'C4': 'תוצאת החוזה', 'D4': 'עלות נטו'}
